#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ipos = 0, ilen = 0;
static inline int gc() {
    if (ipos == ilen) { ilen = fread(ibuf, 1, sizeof ibuf, stdin); ipos = 0; if (!ilen) return -1; }
    return ibuf[ipos++];
}
static inline long long readInt() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return neg ? -x : x;
}

int main() {
    int h = readInt(), w = readInt(), r = readInt(), c = readInt();
    long long nv = readInt();
    vector<long long> a((size_t)h * w);
    for (auto& x : a) x = readInt();
    int start = r * w + c;
    long long old = a[start];
    if (old != nv) {
        // BFS; recoloring on enqueue doubles as the visited mark.
        vector<int> q;
        q.reserve(a.size());
        q.push_back(start);
        a[start] = nv;
        for (size_t head = 0; head < q.size(); head++) {
            int i = q[head], row = i / w, col = i % w;
            auto visit = [&](int j) { if (a[j] == old) { a[j] = nv; q.push_back(j); } };
            if (row) visit(i - w);
            if (row + 1 < h) visit(i + w);
            if (col) visit(i - 1);
            if (col + 1 < w) visit(i + 1);
        }
    }
    string out;
    out.reserve(a.size() * 4);
    char tmp[24];
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int len = snprintf(tmp, sizeof tmp, "%lld", a[(size_t)i * w + j]);
            out.append(tmp, len);
            out += j + 1 < w ? ' ' : '\n';
        }
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;

public class Main {
    static DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

    static long readLong() throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long x = 0;
        while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = in.read(); }
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        int h = (int) readLong(), w = (int) readLong(), r = (int) readLong(), c = (int) readLong();
        long nv = readLong();
        long[] a = new long[h * w];
        for (int i = 0; i < a.length; i++) a[i] = readLong();
        int start = r * w + c;
        long old = a[start];
        if (old != nv) {
            // BFS; recoloring on enqueue doubles as the visited mark.
            int[] q = new int[a.length];
            int head = 0, tail = 0;
            q[tail++] = start;
            a[start] = nv;
            while (head < tail) {
                int i = q[head++], row = i / w, col = i % w;
                if (row > 0 && a[i - w] == old) { a[i - w] = nv; q[tail++] = i - w; }
                if (row + 1 < h && a[i + w] == old) { a[i + w] = nv; q[tail++] = i + w; }
                if (col > 0 && a[i - 1] == old) { a[i - 1] = nv; q[tail++] = i - 1; }
                if (col + 1 < w && a[i + 1] == old) { a[i + 1] = nv; q[tail++] = i + 1; }
            }
        }
        StringBuilder out = new StringBuilder(a.length * 4);
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                out.append(a[i * w + j]).append(j + 1 < w ? ' ' : '\n');
            }
        }
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        pw.print(out);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, _ := reader.ReadByte()
	for c != '-' && (c < '0' || c > '9') {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	var x int64
	for c >= '0' && c <= '9' {
		x = x*10 + int64(c-'0')
		var err error
		c, err = reader.ReadByte()
		if err != nil {
			break
		}
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	h, w, r, c := int(readInt()), int(readInt()), int(readInt()), int(readInt())
	nv := readInt()
	a := make([]int64, h*w)
	for i := range a {
		a[i] = readInt()
	}
	start := r*w + c
	old := a[start]
	if old != nv {
		// BFS; recoloring on enqueue doubles as the visited mark.
		q := make([]int, 0, len(a))
		q = append(q, start)
		a[start] = nv
		for head := 0; head < len(q); head++ {
			i := q[head]
			row, col := i/w, i%w
			visit := func(j int) {
				if a[j] == old {
					a[j] = nv
					q = append(q, j)
				}
			}
			if row > 0 {
				visit(i - w)
			}
			if row+1 < h {
				visit(i + w)
			}
			if col > 0 {
				visit(i - 1)
			}
			if col+1 < w {
				visit(i + 1)
			}
		}
	}
	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer out.Flush()
	buf := []byte{}
	for i := 0; i < h; i++ {
		buf = buf[:0]
		for j := 0; j < w; j++ {
			buf = strconv.AppendInt(buf, a[i*w+j], 10)
			if j+1 < w {
				buf = append(buf, ' ')
			} else {
				buf = append(buf, '\n')
			}
		}
		out.Write(buf)
	}
}
